     6→// ---------- Live Citation Count (Semantic Scholar API) ----------
     7→(function fetchLiveCitations() {
     8→  var url = 'https://api.semanticscholar.org/graph/v1/author/search' +
     9→    '?query=Getnet+Demil+Jenberia&fields=name,citationCount,paperCount,hIndex&limit=5';
    10→
    11→  fetch(url)
    12→    .then(function (r) { return r.json(); })
    13→    .then(function (data) {
    14→      if (!data.data || !data.data.length) return;
    15→      var best = null;
    16→      data.data.forEach(function (author) {
    17→        var name = (author.name || '').toLowerCase();
    18→        if (name.indexOf('getnet') === -1) return;
    19→        if (!best || (author.citationCount || 0) > (best.citationCount || 0)) {
    20→          best = author;
    21→        }
    22→      });
    23→      if (!best || !best.citationCount) return;
    24→      var citEl = document.querySelector('.metric-number[data-count]');
    25→      if (citEl) {
    26→        citEl.setAttribute('data-count', best.citationCount);
    27→        var subtitleEl = document.querySelector('#publications .section-subtitle');
    28→        if (subtitleEl) {
    29→          subtitleEl.innerHTML = subtitleEl.innerHTML.replace(
    30→            /\d+\+?\s*citations/i,
    31→            best.citationCount + '+ citations'
    32→          );
    33→        }
    34→      }
    35→    })
    36→    .catch(function () { /* keep static fallback */ });
    37→})();
