    39→// ---------- Medium RSS Feed (via rss2json.com) ----------
    40→(function initMediumFeed() {
    41→  var container = document.getElementById('mediumFeed');
    42→  if (!container) return;
    43→
    44→  var RSS = 'https://medium.com/feed/@getnetdemil';
    45→  var API = 'https://api.rss2json.com/v1/api.json?rss_url=' + encodeURIComponent(RSS) + '&count=10';
    46→
    47→  function stripTags(str) { return (str || '').replace(/<[^>]+>/g, ''); }
    48→
    49→  function truncate(str, max) {
    50→    var plain = stripTags(str);
    51→    return plain.length > max ? plain.slice(0, max).trimEnd() + '\u2026' : plain;
    52→  }
    53→
    54→  function formatDate(dateStr) {
    55→    var d = new Date(dateStr);
    56→    if (isNaN(d)) return '';
    57→    return d.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
    58→  }
    59→
    60→  function readTime(content) {
    61→    var words = stripTags(content || '').split(/\s+/).filter(Boolean).length;
    62→    return Math.max(1, Math.round(words / 200)) + ' min read';
    63→  }
    64→
    65→  function render(posts) {
    66→    var badge = document.getElementById('mediumBadge');
    67→    if (badge) badge.textContent = posts.length;
    68→
    69→    var html = posts.map(function (p) {
    70→      return '<article class="medium-card fade-in">' +
    71→        '<div class="medium-card-meta">' +
    72→          '<time class="medium-date">' + formatDate(p.pubDate) + '</time>' +
    73→          '<span class="medium-read">' + readTime(p.content || p.description) + '</span>' +
    74→        '</div>' +
    75→        '<h3 class="medium-title">' +
    76→          '<a href="' + p.link + '" target="_blank" rel="noopener noreferrer">' +
    77→          (p.title || 'Untitled') + '</a>' +
    78→        '</h3>' +
    79→        '<p class="medium-excerpt">' + truncate(p.description, 140) + '</p>' +
    80→        '<a class="medium-read-link" href="' + p.link + '" target="_blank" rel="noopener noreferrer">' +
    81→          'Read on Medium \u2192' +
    82→        '</a>' +
    83→      '</article>';
    84→    }).join('');
    85→
    86→    // LinkedIn CTA card
    87→    html += '<div class="medium-card medium-card--linkedin fade-in">' +
    88→      '<div class="medium-card-meta"><span class="medium-read">Professional updates</span></div>' +
    89→      '<h3 class="medium-title">Follow on LinkedIn</h3>' +
    90→      '<p class="medium-excerpt">Research updates, conference posts, and collaboration opportunities.</p>' +
    91→      '<a class="medium-read-link" href="https://www.linkedin.com/in/getnetdemil/" target="_blank" rel="noopener noreferrer">' +
    92→        'View LinkedIn Profile \u2192' +
    93→      '</a>' +
    94→    '</div>';
    95→
    96→    container.innerHTML = html;
    97→
    98→    // Trigger fade-in for newly rendered cards
    99→    container.querySelectorAll('.fade-in').forEach(function (el) {
   100→      fadeObserverInstance && fadeObserverInstance.observe(el);
   101→    });
   102→  }
   103→
   104→  fetch(API)
   105→    .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
   106→    .then(function (data) {
   107→      if (data.status === 'ok' && data.items && data.items.length) {
   108→        render(data.items);
   109→      } else {
   110→        throw new Error('No items');
   111→      }
   112→    })
   113→    .catch(function () {
   114→      container.innerHTML =
   115→        '<p class="medium-empty">Could not load posts. ' +
   116→        '<a href="https://medium.com/@getnetdemil" target="_blank" rel="noopener noreferrer">' +
   117→        'Read on Medium \u2192</a></p>';
   118→    });
   119→})();
