   121→// ---------- News Tabs ----------
   122→(function initNewsTabs() {
   123→  var tabs   = document.querySelectorAll('.news-tab');
   124→  var panels = document.querySelectorAll('[role="tabpanel"]');
   125→  if (!tabs.length) return;
   126→
   127→  tabs.forEach(function (tab) {
   128→    tab.addEventListener('click', function () {
   129→      var target = tab.getAttribute('data-tab');
   130→      tabs.forEach(function (t) {
   131→        t.classList.remove('active');
   132→        t.setAttribute('aria-selected', 'false');
   133→      });
   134→      tab.classList.add('active');
   135→      tab.setAttribute('aria-selected', 'true');
   136→      panels.forEach(function (panel) {
   137→        panel.hidden = (panel.id !== 'tab-' + target);
   138→      });
   139→    });
   140→  });
   141→})();
