   143→// ---------- See More / Collapse (universal) ----------
   144→(function initSeeMore() {
   145→  document.querySelectorAll('[data-see-more]').forEach(function (container) {
   146→    var max    = parseInt(container.getAttribute('data-see-more'), 10);
   147→    var items  = Array.from(container.children);
   148→    var wrap   = container.nextElementSibling;
   149→    var btn    = wrap && wrap.classList.contains('see-more-wrap')
   150→                   ? wrap.querySelector('.see-more-btn') : null;
   151→    var icon   = btn && btn.querySelector('.see-more-icon');
   152→    var hidden = items.slice(max);
   153→
   154→    if (!btn || !hidden.length) {
   155→      if (wrap && wrap.classList.contains('see-more-wrap')) wrap.hidden = true;
   156→      return;
   157→    }
   158→
   159→    hidden.forEach(function (el) { el.hidden = true; });
   160→
   161→    btn.addEventListener('click', function () {
   162→      var isOpen = btn.getAttribute('aria-expanded') === 'true';
   163→      hidden.forEach(function (el) { el.hidden = isOpen; });
   164→      btn.setAttribute('aria-expanded', String(!isOpen));
   165→
   166→      // Swap label text
   167→      var labelMore = btn.getAttribute('data-label-more') || 'Show more';
   168→      var labelLess = btn.getAttribute('data-label-less') || 'Show less';
   169→      // Update only the text node (first child)
   170→      var textNode = Array.from(btn.childNodes).find(function (n) { return n.nodeType === 3; });
   171→      if (textNode) textNode.textContent = isOpen ? labelMore + ' ' : labelLess + ' ';
   172→
   173→      if (icon) icon.style.transform = isOpen ? '' : 'rotate(180deg)';
   174→      if (!isOpen && hidden[0]) {
   175→        hidden[0].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
   176→      }
   177→    });
   178→  });
   179→})();
