   181→// ---------- Theme Toggle ----------
   182→(function initTheme() {
   183→  var saved = localStorage.getItem('theme') || 'dark';
   184→  document.documentElement.setAttribute('data-theme', saved);
   185→})();
   186→
   187→var themeToggle = document.getElementById('themeToggle');
   188→if (themeToggle) {
   189→  themeToggle.addEventListener('click', function () {
   190→    var current = document.documentElement.getAttribute('data-theme');
   191→    var next = current === 'dark' ? 'light' : 'dark';
   192→    document.documentElement.setAttribute('data-theme', next);
   193→    localStorage.setItem('theme', next);
   194→  });
   195→}
