   197→// ---------- Scroll Progress Bar ----------
   198→var progressBar = document.getElementById('scroll-progress');
   199→function updateScrollProgress() {
   200→  if (!progressBar) return;
   201→  var scrollTop  = window.scrollY || document.documentElement.scrollTop;
   202→  var docHeight  = document.documentElement.scrollHeight - window.innerHeight;
   203→  var pct        = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
   204→  progressBar.style.width = pct + '%';
   205→}
   206→window.addEventListener('scroll', updateScrollProgress, { passive: true });
   207→
   208→// ---------- Navbar scroll effect ----------
   209→var navbar = document.getElementById('navbar');
   210→function handleNavbarScroll() {
   211→  if (!navbar) return;
   212→  if (window.scrollY > 20) {
   213→    navbar.classList.add('scrolled');
   214→  } else {
   215→    navbar.classList.remove('scrolled');
   216→  }
   217→}
   218→window.addEventListener('scroll', handleNavbarScroll, { passive: true });
   219→
   220→// ---------- Mobile nav toggle ----------
   221→var navToggle = document.getElementById('navToggle');
   222→var navLinks  = document.getElementById('navLinks');
   223→
   224→if (navToggle && navLinks) {
   225→  navToggle.addEventListener('click', function () {
   226→    var isOpen = navLinks.classList.toggle('open');
   227→    navToggle.setAttribute('aria-expanded', String(isOpen));
   228→  });
   229→  navLinks.querySelectorAll('a').forEach(function (link) {
   230→    link.addEventListener('click', function () {
   231→      navLinks.classList.remove('open');
   232→      navToggle.setAttribute('aria-expanded', 'false');
   233→    });
   234→  });
   235→}
   236→
   237→// ---------- Active nav link on scroll ----------
   238→var sections = document.querySelectorAll('section[id]');
   239→var navItems = document.querySelectorAll('.nav-links a');
   240→
   241→function updateActiveNavLink() {
   242→  var scrollPos = window.scrollY + 120;
   243→  sections.forEach(function (section) {
   244→    if (scrollPos >= section.offsetTop && scrollPos < section.offsetTop + section.offsetHeight) {
   245→      navItems.forEach(function (a) {
   246→        a.classList.remove('active');
   247→        if (a.getAttribute('href') === '#' + section.id) a.classList.add('active');
   248→      });
   249→    }
   250→  });
   251→}
   252→window.addEventListener('scroll', updateActiveNavLink, { passive: true });
