   254→// ---------- Animated Counters ----------
   255→function animateCounter(el) {
   256→  var target   = parseInt(el.getAttribute('data-count'), 10);
   257→  var duration = 1400;
   258→  var start    = null;
   259→  function step(ts) {
   260→    if (!start) start = ts;
   261→    var progress = Math.min((ts - start) / duration, 1);
   262→    var eased = 1 - Math.pow(1 - progress, 3);
   263→    el.textContent = Math.round(eased * target);
   264→    if (progress < 1) requestAnimationFrame(step);
   265→  }
   266→  requestAnimationFrame(step);
   267→}
