   269→var counterEls   = document.querySelectorAll('.metric-number[data-count]');
   270→var countersSeen = false;
   271→var counterObserver = new IntersectionObserver(function (entries) {
   272→  entries.forEach(function (entry) {
   273→    if (entry.isIntersecting && !countersSeen) {
   274→      countersSeen = true;
   275→      counterEls.forEach(animateCounter);
   276→      counterObserver.disconnect();
   277→    }
   278→  });
   279→}, { threshold: 0.3 });
   280→if (counterEls.length > 0) {
   281→  counterObserver.observe(counterEls[0].closest('.about-metrics') || counterEls[0]);
   282→}
   283→
   284→// ---------- Timeline item scroll animations ----------
   285→var tlObserver = new IntersectionObserver(function (entries) {
   286→  entries.forEach(function (entry) {
   287→    if (entry.isIntersecting) {
   288→      entry.target.classList.add('tl-item--visible');
   289→      tlObserver.unobserve(entry.target);
   290→    }
   291→  });
   292→}, { threshold: 0.1 });
   293→
   294→// Observe all timeline items and set stagger delays
   295→document.querySelectorAll('.tl-item').forEach(function (el, i) {
   296→  el.style.setProperty('--delay', (i % 5) * 80 + 'ms');
   297→  tlObserver.observe(el);
   298→});
   299→
   300→// ---------- Fade-in on scroll ----------
   301→var fadeEls = document.querySelectorAll(
   302→  '.highlight-card, .interest-card, .publication-card, .contact-card, ' +
   303→  '.project-card, .project-card-full, .news-card, .service-block, .skill-item'
   304→);
   305→
   306→var fadeObserverInstance = new IntersectionObserver(function (entries) {
   307→  entries.forEach(function (entry) {
   308→    if (entry.isIntersecting) {
   309→      entry.target.classList.add('visible');
   310→      fadeObserverInstance.unobserve(entry.target);
   311→    }
   312→  });
   313→}, { threshold: 0.08 });
   314→
   315→fadeEls.forEach(function (el) {
   316→  el.classList.add('fade-in');
   317→  fadeObserverInstance.observe(el);
   318→});
   319→
   320→// ---------- Publication search ----------
   321→var pubSearch     = document.getElementById('pubSearch');
   322→var pubCards      = document.querySelectorAll('.publication-card');
   323→var pubYearGroups = document.querySelectorAll('.pub-year-group');
   324→var pubNoResults  = document.getElementById('pubNoResults');
   325→var activeFilter  = 'all';
   326→
   327→function filterPublications() {
   328→  var query   = pubSearch ? pubSearch.value.toLowerCase().trim() : '';
   329→  var visible = 0;
   330→  pubCards.forEach(function (card) {
   331→    var type     = (card.getAttribute('data-type') || '').toLowerCase();
   332→    var text     = card.textContent.toLowerCase();
   333→    var matchesQ = !query || text.indexOf(query) !== -1;
   334→    var matchesF = activeFilter === 'all' || type === activeFilter;
   335→    if (matchesQ && matchesF) { card.style.display = ''; visible++; }
   336→    else { card.style.display = 'none'; }
   337→  });
   338→  pubYearGroups.forEach(function (group) {
   339→    var cards = group.querySelectorAll('.publication-card');
   340→    var any   = false;
   341→    cards.forEach(function (c) { if (c.style.display !== 'none') any = true; });
   342→    group.style.display = any ? '' : 'none';
   343→  });
   344→  if (pubNoResults) pubNoResults.classList.toggle('visible', visible === 0);
   345→}
   346→
   347→if (pubSearch) pubSearch.addEventListener('input', filterPublications);
   348→
   349→var filterBtns = document.querySelectorAll('.filter-btn');
   350→filterBtns.forEach(function (btn) {
   351→  btn.addEventListener('click', function () {
   352→    filterBtns.forEach(function (b) { b.classList.remove('active'); });
   353→    btn.classList.add('active');
   354→    activeFilter = btn.getAttribute('data-filter');
   355→    filterPublications();
   356→  });
   357→});
   358→
   359→// ---------- FlowCV iframe error handling ----------
   360→(function () {
   361→  var iframe = document.querySelector('.flowcv-iframe');
   362→  if (!iframe) return;
   363→  iframe.addEventListener('error', function () {
   364→    var wrap = iframe.closest('.flowcv-wrap');
   365→    if (wrap) wrap.classList.add('flowcv-wrap--error');
   366→  });
   367→})();
   368→
   369→// ---------- Footer year ----------
   370→var yearEl = document.getElementById('year');
   371→if (yearEl) yearEl.textContent = new Date().getFullYear();
   372→
   373→// ---------- Nav brand: scroll to top, no hash in URL ----------
   374→var navBrand = document.querySelector('.nav-brand');
   375→if (navBrand) {
   376→  navBrand.addEventListener('click', function (e) {
   377→    e.preventDefault();
   378→    window.scrollTo({ top: 0, behavior: 'smooth' });
   379→    history.replaceState(null, '', '/');
   380→  });
   381→}
   382→
   383→// Run once at init
   384→handleNavbarScroll();
   385→updateActiveNavLink();
